from collections import Counter

def findValidPair(s: str) -> str:
    count = Counter(s)
    for i in range(len(s) - 1):
        if s[i] != s[i + 1]:
            first_digit = int(s[i])
            second_digit = int(s[i + 1])
            if count[s[i]] == first_digit and count[s[i + 1]] == second_digit:
                return s[i] + s[i + 1]
    return ""

def maxDifference(s: str) -> int:
    from collections import Counter
    frequency = Counter(s)
    max_odd = -1
    min_even = float('inf')

    for count in frequency.values():
        if count % 2 == 0:
            min_even = min(min_even, count)
        else:
            max_odd = max(max_odd, count)

    return max_odd - min_even

