from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    offline_until = [0] * numberOfUsers
    sorted_events = sorted(events, key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1))

    for event in sorted_events:
        event_type, timestamp_str, *args = event
        timestamp = int(timestamp_str)

        if event_type == "OFFLINE":
            user_id = int(args[0])
            online_status[user_id] = False
            offline_until[user_id] = timestamp + 60

        elif event_type == "MESSAGE":
            # Update online status for users that should come back online
            for user_id in range(numberOfUsers):
                if not online_status[user_id] and timestamp >= offline_until[user_id]:
                    online_status[user_id] = True

            mentions_string = args[0]
            if mentions_string == "ALL":
                for user_id in range(numberOfUsers):
                    mentions[user_id] += 1
            elif mentions_string == "HERE":
                for user_id in range(numberOfUsers):
                    if online_status[user_id]:
                        mentions[user_id] += 1
            else:
                mentioned_ids = mentions_string.split()
                for mention in mentioned_ids:
                    user_id = int(mention[2:])
                    mentions[user_id] += 1

    return mentions

def maxDistance(s: str, k: int) -> int:
    # Initialize the starting position and maximum distance
    x, y = 0, 0
    max_distance = 0
    n = len(s)

    # Iterate over each move to track position and calculate maximum distance
    for i in range(n):
        if s[i] == 'N':
            y += 1
        elif s[i] == 'S':
            y -= 1
        elif s[i] == 'E':
            x += 1
        elif s[i] == 'W':
            x -= 1

        # Calculate the candidate maximum distance
        candidate = min(i + 1, abs(x) + abs(y) + 2 * k)
        max_distance = max(max_distance, candidate)

    return max_distance
